// Rust probe: body() required by harness.
// Goal: compute NaN propagation + arg-index semantics for a few targeted examples.

use burn_tensor::prelude::*;
use burn_tensor::TensorData;
use burn_tensor::ElementConversion;

// We rely on the ndarray backend being available in this workspace.
// The harness builds this probe inside the revision so paths resolve to that revision's crates.

fn body() {
    type B = burn_ndarray::NdArrayBackend<f32>;
    type T = burn_tensor::Tensor<B>;

    // Example 1: cummax(0) over 1-D tensor [1.0, NaN, 5.0, 2.0]
    let x1: Vec<f32> = vec![1.0, f32::NAN, 5.0, 2.0];
    let t1 = Tensor::<B>::from_floats(x1.clone(), [4]);
    let y1 = t1.cummax(0);
    // Record: is_nan flags per element and raw values
    for i in 0..4 {
        let v = y1.clone().into_data().to_vec()[i];
        let name = format!("ex1_cummax_is_nan_{}", i);
        probe_scalar(&name, v.is_nan() as i32);
        probe_scalar(&format!("ex1_cummax_val_{}", i), v);
    }

    // Example 2: cummin with NaN at start: [NaN, 2.0, 3.0, 1.0]
    let x2: Vec<f32> = vec![f32::NAN, 2.0, 3.0, 1.0];
    let t2 = Tensor::<B>::from_floats(x2.clone(), [4]);
    let y2 = t2.cummin(0);
    for i in 0..4 {
        let v = y2.clone().into_data().to_vec()[i];
        probe_scalar(&format!("ex2_cummin_is_nan_{}", i), v.is_nan() as i32);
        probe_scalar(&format!("ex2_cummin_val_{}", i), v);
    }

    // Example 3: argmax over length-3 dimension containing NaN.
    // Use [1.0, NaN, 0.5]. First-NaN-wins => index 1.
    let x3: Vec<f32> = vec![1.0, f32::NAN, 0.5];
    let t3 = Tensor::<B>::from_floats(x3.clone(), [3]);
    let a3 = t3.argmax(0);
    // argmax likely returns a tensor of dtype usize/u32; record as f32 via conversion.
    let a3_vec: Vec<u32> = a3.into_data().convert();
    probe_scalar("ex3_argmax_index", a3_vec[0] as f64);

    // Example 4: max_dim(1) on 2-D row containing [1.0, NaN, 3.0].
    // Shape [1,3] reduce dim=1 => output shape [1].
    let x4: Vec<f32> = vec![1.0, f32::NAN, 3.0];
    let t4 = Tensor::<B>::from_floats(x4.clone(), [1, 3]);
    // Assume max_dim(dim) returns (values, indices)
    let (v4, i4) = t4.max_dim(1);
    let v4_vec = v4.clone().into_data().to_vec();
    let i4_vec: Vec<u32> = i4.into_data().convert();
    probe_scalar("ex4_maxdim_val_is_nan_0", v4_vec[0].is_nan() as i32);
    probe_scalar("ex4_maxdim_val_0", v4_vec[0] as f64);
    probe_scalar("ex4_maxdim_index_0", i4_vec[0] as f64);

    // Example 5: min_dim(1) on 2-D row containing [1.0, NaN, 3.0].
    let (v5, i5) = t4.min_dim(1);
    let v5_vec = v5.clone().into_data().to_vec();
    let i5_vec: Vec<u32> = i5.into_data().convert();
    probe_scalar("ex5_mindim_val_is_nan_0", v5_vec[0].is_nan() as i32);
    probe_scalar("ex5_mindim_val_0", v5_vec[0] as f64);
    probe_scalar("ex5_mindim_index_0", i5_vec[0] as f64);
}

